import { tags } from "typia";

/**
 * Distribution of moderator action types among all resolved reports. Shows the
 * balance between different moderation tools (dismiss, remove, warn,
 * suspension, ban). Helps assess whether moderation is appropriately
 * calibrated, minimizing overuse or underuse of penalty actions.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscussionBoardArticleAggregatedReportModeratorActionTypeDistribution =
  {
    /**
     * Number of reports where moderators chose to dismiss the report without
     * taking any action on the content. Indicates reports that were deemed
     * invalid, unfounded, or not violating community guidelines.
     */
    dismiss: number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Number of reports where moderators removed the reported article from
     * public view. Indicates serious policy violations that warranted content
     * removal while preserving the article in system archives for audit
     * purposes.
     */
    remove: number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Number of reports where moderators issued a warning to the article's
     * author. Used for minor or first-time violations as a corrective measure
     * to notify users of policy breaches without removing content.
     */
    warn: number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Number of reports where moderators imposed a temporary suspension on the
     * author's account. Indicates repeated or severe violations requiring
     * temporary withdrawal of posting privileges to allow for reflection and
     * rehabilitation.
     */
    suspension: number & tags.Type<"int32"> & tags.Minimum<0>;

    /**
     * Number of reports where moderators imposed a permanent ban on the
     * author's account. Indicates severe, repeated, or egregious violations
     * that demonstrate an unwillingness to comply with community guidelines.
     */
    ban: number & tags.Type<"int32"> & tags.Minimum<0>;
  };
